import{_ as a,o as i,c as e,am as t}from"./chunks/framework._FJXuPhs.js";const c=JSON.parse('{"title":"架构篇","description":"","frontmatter":{"title":"架构篇","excerpt":"摘要","date":"2026-04-23 15:44:25","updated":"2026-04-23 15:44:25"},"headers":[],"relativePath":"架构篇/index.md","filePath":"架构篇/index.md","lastUpdated":null}'),r={name:"架构篇/index.md"};function o(n,l,s,u,h,d){return i(),e("div",null,[...l[0]||(l[0]=[t('<h3 id="系统架构设计" tabindex="-1">系统架构设计 <a class="header-anchor" href="#系统架构设计" aria-label="Permalink to &quot;系统架构设计&quot;">​</a></h3><p><a href="/java-site/架构篇/业务场景和技术选型/系统架构设计/">Java体系— 架构 系统架构设计</a></p><h3 id="分布式系统" tabindex="-1">分布式系统 <a class="header-anchor" href="#分布式系统" aria-label="Permalink to &quot;分布式系统&quot;">​</a></h3><p><a href="/java-site/架构篇/分布式系统/">Java体系— 架构 分布式系统</a></p><h3 id="高并发与性能优化" tabindex="-1">高并发与性能优化 <a class="header-anchor" href="#高并发与性能优化" aria-label="Permalink to &quot;高并发与性能优化&quot;">​</a></h3><ul><li><strong>高并发架构</strong>： <ul><li>缓存体系（Redis、Guava Cache、Caffeine）</li><li>消息队列（Kafka、RabbitMQ、RocketMQ）</li><li>异步任务执行（线程池、CompletableFuture）</li></ul></li><li><strong>性能调优</strong>： <ul><li>JVM 调优（GC 策略、内存模型）</li><li>数据库调优（索引优化、SQL 优化）</li><li>I/O优化（零拷贝、NIO/Netty）</li></ul></li><li><strong>容量规划</strong>： <ul><li>并发数预估</li><li>QPS、TPS 计算</li><li>压测（JMeter、Gatling）</li></ul></li></ul><h3 id="数据与存储" tabindex="-1">数据与存储 <a class="header-anchor" href="#数据与存储" aria-label="Permalink to &quot;数据与存储&quot;">​</a></h3><ul><li><strong>数据库架构</strong>： <ul><li>主从复制、读写分离</li><li>分库分表（ShardingSphere、MyCat）</li></ul></li><li><strong>缓存架构</strong>： <ul><li>本地缓存 + 分布式缓存</li><li>缓存更新策略（失效、主动刷新、双写一致）</li></ul></li><li><strong>大数据与数据分析</strong>： <ul><li>Hadoop、Spark</li><li>ElasticSearch（全文检索）</li></ul></li></ul><h3 id="安全与可观测性" tabindex="-1">安全与可观测性 <a class="header-anchor" href="#安全与可观测性" aria-label="Permalink to &quot;安全与可观测性&quot;">​</a></h3><p><a href="/java-site/架构篇/系统设计_数据安全/架构 安全与可观测性.html">Java体系— 架构 安全与可观测性</a></p><ul><li><strong>安全</strong>： <ul><li>HTTPS/TLS</li><li>JWT/OAuth2</li><li>XSS、CSRF、SQL注入防护</li></ul></li><li><strong>可观测性</strong>： <ul><li>日志（ELK）</li><li>监控（Prometheus + Grafana）</li><li>链路追踪（Zipkin、Jaeger）</li></ul></li></ul><p>监控</p><p>HertzBeat（赫兹跳动）: <a href="https://mp.weixin.qq.com/s/3llRao8Z7WRIDnxV6RkgpQ" target="_blank" rel="noreferrer">https://mp.weixin.qq.com/s/3llRao8Z7WRIDnxV6RkgpQ</a></p><h3 id="运维与devops" tabindex="-1">运维与DevOps <a class="header-anchor" href="#运维与devops" aria-label="Permalink to &quot;运维与DevOps&quot;">​</a></h3><ul><li>Docker 容器化</li><li>Kubernetes 编排与微服务部署</li><li>CI/CD（Jenkins、GitLab CI）</li><li>自动化运维与配置管理（Ansible、SaltStack）</li></ul>',15)])])}const f=a(r,[["render",o]]);export{c as __pageData,f as default};
